package pl.zagranietyper.parser;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class FootballTeamToAdvanceSyntaxAdapterTest {private final FootballTeamToAdvanceSyntaxAdapter p=new FootballTeamToAdvanceSyntaxAdapter();@Test void parsesWholeDeterministicMarket(){assertTrue(p.parse("Barcelona awansuje do finału Ligi Mistrzów","Inter","Barcelona").parsed());assertTrue(p.parse("awans Interu","Inter","Bayern München").parsed());assertTrue(p.parse("Awans Arsenalu z Manchesterem United","Arsenal","Manchester United").parsed());}@Test void rejectsRegulationQualifierOutrightGroupAndPartial(){assertFalse(p.parse("Inter awansuje w reg. czasie gry","Inter","Bayern").parsed());assertFalse(p.parse("Inter wygra Ligę Mistrzów","Inter","Bayern").parsed());assertFalse(p.parse("Inter wyjdzie z grupy","Inter","Bayern").parsed());assertFalse(p.parse("Inter awansuje i wygra mecz","Inter","Bayern").parsed());}@Test void unresolvedParticipantRejected(){assertEquals(FootballTeamToAdvanceSyntaxAdapter.Status.PARTICIPANT_UNRESOLVED,p.parse("Turcja awansuje","Slovakia","Romania").status());}}
